def fail(msg):
    print("")
    print("FAILURE: %s" % msg)
    print("NOTHING was written.")
    print("Undo is Discard Changes in GitHub Desktop.")
    return 1


def main():
    here = os.path.basename(os.path.abspath(os.getcwd())).lower()
    if not os.path.isfile(PAGE) or here in ("documentation", "gallery", "tools"):
        return fail(
            "index.html is not here (%s).\n"
            "         Run this from the GALLERY repo root -- the folder that\n"
            "         holds index.html -- not from gallery/, tools/ or\n"
            "         documentation/, and not from the orrery repo."
            % os.getcwd())

    art = base64.b64decode(ART_B64)
    if hashlib.md5(art).hexdigest() != ART_MD5:
        return fail("the art carried in this script is damaged.")
    write_art = True
    if os.path.exists(ART):
        if hashlib.md5(open(ART, "rb").read()).hexdigest() != ART_MD5:
            return fail("%s is already here with different bytes. Tell\n"
                        "         Claude; do not delete it by hand." % ART)
        write_art = False

    raw = open(PAGE, "rb").read()
    was_crlf = b"\r\n" in raw
    content = raw.replace(b"\r\n", b"\n") if was_crlf else raw
    actual = hashlib.md5(content).hexdigest()
    if actual == RESULT:
        return fail("this patch has already been applied: index.html\n"
                    "         already has the dusk wall.")
    if actual != EXPECTED:
        return fail(
            "BASE MOVED. index.html is not the file this patch was built\n"
            "         against (gallery 2e164816).\n"
            "         expected %s\n"
            "         found    %s\n"
            "         (Line endings were normalised before comparing, so\n"
            "         CRLF does not explain this -- the content differs.\n"
            "         Tell Claude; do not edit the file by hand.)"
            % (EXPECTED, actual))
    if was_crlf:
        print("note: index.html is CRLF here; compared normalised, written")
        print("      back CRLF exactly as found.")
    out = content
    for label, old, new in EDITS_PAGE:
        count = out.count(old)
        if count != 1:
            return fail("ANCHOR FAIL: expected 1 match, found %d for: %s"
                        % (count, label))
        out = out.replace(old, new)
        print("  ok  %s" % label)
    if any(byt > 127 for byt in out):
        return fail("non-ASCII text would be written; refusing")
    print("  ok  encoding gate: index.html is ASCII after the edit")
    if hashlib.md5(out).hexdigest() != RESULT:
        return fail("the result is not the file this patch was built and\n"
                    "         tested to produce.")
    print("  ok  the result is the file that was tested")

    if write_art:
        with open(ART, "wb") as handle:
            handle.write(art)
        print("  wrote %s (%d bytes)" % (ART, len(art)))
    else:
        print("  ok  %s was already here, byte for byte" % ART)
    final = out.replace(b"\n", b"\r\n") if was_crlf else out
    with open(PAGE, "wb") as handle:
        handle.write(final)
    print("  wrote index.html (%d bytes)%s"
          % (len(final), " [CRLF, as found]" if was_crlf else ""))

    print("")
    print("patch applied to 2 files")
    print("")
    print("Stamps updated: the 'Updated' line at the top of index.html.")
    print("")
    print("WHAT TO DO NEXT, in this order:")
    print("")
    print("  1. Move THIS script into documentation/. It has run. Move")
    print("     patch_L286_3_rooms_and_header_20260924.py there too; it was")
    print("     committed at the repo root.")
    print("  2. Run the gallery maintenance run:")
    print("         python gallery_maintenance_run.py")
    print("     Expect every gating checker to pass, as before.")
    print("  3. In GitHub Desktop the change list should show index.html,")
    print("     palomas_orrery_wall.jpg (new), this script under")
    print("     documentation/, and the rooms script moving into")
    print("     documentation/. Commit and push.")
    print("  4. After the push, check what the live site serves:")
    print("         python gallery_maintenance_run.py --live")
    print("  5. On the phone, wait about ten minutes after the push, close the")
    print("     page and open it again, then:")
    print("       - The lobby stands on the dusk sky with the moon and birds.")
    print("       - A room shows them fainter.")
    print("       - An open card is on black, as before.")
    print("       - The i button in the lobby: the credit names Gemini.")
    print("     The same on the desktop.")
    print("  6. Tell Claude the new gallery SHA and what you saw.")
    print("")
    print("TONY-ACTION ROLLUP for this patch:")
    print("  (do)     steps 1 to 6 above.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
